function getPerson(){return (state.people||[]).find(p=>p.id===state.userId)||{id:state.userId,name:'示範學員',branch:'營業一店',department:'財務部',businessLine:'財務',counter:'C001',role:'專櫃',status:'啟用'};}
function getLearner(id=state.userId){state.learners??={};if(!state.learners[id])state.learners[id]={courses:{cash:{units:id==='demo-a'?[0]:[],attempts:[],passed:false},invoice:{units:[],attempts:[],passed:false}},notices:{},surveys:{}};const l=state.learners[id];l.courses??={};l.notices??={};l.surveys??={};return l;}
function receipt(n){const l=getLearner(),key=n.id+':'+n.version;return l.notices[key]||(l.notices[key]={readAt:null,signedAt:null});}
function seedNotices(){if(Array.isArray(state.noticeCatalog)){const n=state.noticeCatalog.find(n=>n.id==='n-cash');if(n){n.image??='assets/cash-u1.png';n.attachments??=[NOTICE_ATTACHMENTS[0]];n.important??=true;}return;}state.noticeCatalog=[{id:'n-cash',image:'assets/cash-u1.png',attachments:[NOTICE_ATTACHMENTS[0]],important:true,title:'收銀結帳作業更新',version:'v1.0',required:true,due:'2026-10-25',status:'已發布',branches:['營業一店','營業二店'],businessLine:'財務',publisher:'財務部',publishedAt:'2026/10/21 09:00',body:'每日結帳核對與異常回報\n\n本公告為會議示範內容，正式作業規範以遠百核定教材為準。\n\n一、交易明細核對\n完成每日作業時，請依單據及核准流程核對付款方式、交易筆數與金額，確認資料完整，避免重複登錄。\n\n二、差異處理\n發現差異時，請保留原始交易紀錄及相關憑證，確認是否涉及作廢、退貨或付款方式異動。\n\n尚未查明原因前，請勿自行刪除紀錄或任意調整結帳資料；應依核准流程記錄差異、處理人員與時間。\n\n三、主管回報\n將異常說明交由主管核對，並依回覆完成後續處理。待辦項目須持續追蹤至結案。\n\n四、交班確認\n交班前再次確認待處理事項、單據與差異紀錄，將尚未完成項目交接予接班同仁。\n\n五、版本與確認\n本次確認對應公告 v1.0。新版本要求重新確認時，原有回條保留，重新閱讀後另建新版確認紀錄。\n\n如有作業疑問，請向所屬分店財務主管確認。'},{id:'n-ticket',image:'',attachments:[],important:false,title:'電子票券核銷流程更新',version:'v1.0',required:true,due:'2026-10-30',status:'已發布',branches:['營業一店','營業二店'],businessLine:'財務',publisher:'財務部',publishedAt:'2026/10/20 09:00',body:'電子票券核銷注意事項\n\n請核對票券效期與適用條件，依正式作業流程完成核銷。\n\n取消交易時，應確認原核銷紀錄與回復結果，遇無法確認的情形保留單據並通知主管。\n\n本內容僅用於會議示範，正式條款及處理流程以財務部核准版本為準。'},{id:'n-resource',image:'',attachments:[],important:false,title:'十月學習資源上線',version:'v1.0',required:false,due:'2026-11-05',status:'已發布',branches:['營業一店','營業二店'],businessLine:'財務',publisher:'教育訓練',publishedAt:'2026/10/18 10:00',body:'十月份學習教材已更新，可前往課程中心接續學習。\n\n本則為一般資訊公告，不須本人簽收。'}];}

const versionKey=v=>String(v??'1').replace(/^v/,'').replace(/\.0+$/,'');
function findNotice(id,version){const all=[...state.noticeCatalog,...(state.noticeVersions||[])];return all.find(n=>n.id===id&&(!version||versionKey(n.version)===versionKey(version)));}
function readableNotice(n){const p=getPerson();return !!n&&n.status==='已發布'&&(!n.businessLine||n.businessLine===p.businessLine)&&(!n.branches?.length||n.branches.includes(p.branch)||(state.assignments||[]).some(a=>a.person===state.userId&&a.noticeId===n.id&&versionKey(a.version)===versionKey(n.version)));}
function activeNotice(){const n=findNotice(state.activeNotice,state.activeNoticeVersion);return readableNotice(n)?n:null;}
function canEditNotice(n){if(!canEditNotices())return false;if(!n)return true;const p=getPerson();return n.businessLine===p.businessLine&&(state.role==='business'||n.branches.length===1&&n.branches[0]===p.branch&&n.ownerBranch===p.branch);}
function visibleNoticePeople(n){const p=getPerson();return state.people.filter(x=>n.branches.includes(x.branch)&&x.businessLine===n.businessLine&&(state.role!=='branch'||x.branch===p.branch));}
function seedLearnerHistory(){if(state.historySeeded)return;for(const a of state.assignments||[]){const l=getLearner(a.person);if(a.type==='notice'&&(a.readAt||a.signedAt)){const n=findNotice(a.noticeId,a.version);if(n)l.notices[n.id+':'+n.version]={readAt:a.readAt||null,signedAt:a.signedAt||null,userId:a.person,version:n.version};}else if(a.type==='course'&&a.status==='已完成'){const c=state.catalog.find(c=>c.id===a.courseId);if(c)l.courses[c.id]={units:[0,1],attempts:[],passed:true,completedAt:a.completedAt,creditedHours:c.hours,courseTitle:c.title,courseVersion:String(c.version),materialVersion:String(c.version),orgSnapshot:{...(a.organizationSnapshot||{})}};}}state.historySeeded=true;}

function getNotices(){const p=getPerson();return state.noticeCatalog.filter(n=>n.status==='已發布'&&(!n.businessLine||n.businessLine===(p.businessLine||'財務'))&&(!n.branches?.length||n.branches.includes(p.branch)||(state.assignments||[]).some(a=>a.person===state.userId&&a.noticeId===n.id)));}
function syncAssignments(){
 for(const a of state.assignments||[]){
  const l=state.learners?.[a.person];if(!l)continue;
  if(a.type==='course'){
   const id=a.courseId||({'收銀結帳與異常處理':'cash','電子發票與退換貨作業':'invoice'})[a.title];if(!id)continue;a.courseId=id;
   const progress=l.courses?.[id],catalog=(state.catalog||[]).find(x=>x.id===id);if(!progress)continue;
   const targetVersion=a.version??catalog?.version??1;
   const c=[progress,...(progress.versionHistory||[])].find(p=>versionKey(p.materialVersion??p.courseVersion??catalog?.version??1)===versionKey(targetVersion));if(!c)continue;
   const passed=x=>x.passed===true||(x.passed==null&&x.score>=Number(catalog?.passScore??60));
   if(a.reinforcement){
    const prior=new Set(a.priorAttemptIds||[]),cutoff=Date.parse(a.requiredAttemptAfter||'');
    const fresh=(c.attempts||[]).filter((x,i)=>{
     if(x.assignmentId&&x.assignmentId!==a.id)return false;
     if(x.cycleId&&a.cycleId&&x.cycleId!==a.cycleId)return false;
     if(x.id&&prior.has(x.id))return false;
     if(!x.id&&i<Number(a.requiredAttemptCount||0))return false;
     const at=Date.parse(x.submittedAt||x.at||'');
     return !Number.isFinite(cutoff)||Number.isFinite(at)&&at>=cutoff;
    });
    const success=fresh.find(passed),latest=fresh.at(-1);
    if(success){a.status='已完成';a.completedAt=success.submittedAt||success.at||stamp();a.score=success.score;a.organizationSnapshot={...(a.organizationSnapshot||{}),...(success.orgSnapshot||success.organizationSnapshot||{})};}
    else if(latest){a.status='測驗未通過';a.score=latest.score;}
    else if(a.status!=='已完成')a.status='待補強';
    if(latest)a.latestPracticeScore=latest.score;
    continue;
   }
   if(c.passed){a.status='已完成';a.completedAt=c.completedAt||a.completedAt||stamp();a.score=c.attempts?.findLast(passed)?.score??a.score;a.latestPracticeScore=c.attempts?.at(-1)?.score??a.score;a.organizationSnapshot={...(a.organizationSnapshot||{}),...(c.orgSnapshot||c.organizationSnapshot||{})};}
   else if(c.attempts?.length){a.status='測驗未通過';a.score=c.attempts.at(-1).score;}else if(c.units?.length)a.status='學習中';
  }else{
   const id=a.noticeId||({'收銀結帳作業更新':'n-cash','電子票券核銷流程更新':'n-ticket'})[a.title],n=findNotice(id,a.version);if(!n)continue;a.noticeId=id;
   const r=l.notices?.[id+':'+n.version];if(r){a.readAt=r.readAt||'';a.signedAt=r.signedAt||'';a.status=r.signedAt?'已確認':r.readAt?'已讀未確認':'未讀';}
  }
 }
}
function gpsSites(){const p=getPerson();if(window.GpsUI?.getApplicableSites)return window.GpsUI.getApplicableSites(p,{activeOnly:true}).filter(g=>g.required!==false);return (state.gpsSites||[]).filter(g=>g.branch===p.branch&&g.required!==false&&g.enabled!==false);}
function getGps(){const sites=gpsSites(),g=sites[0];return g?{...g,interval:Math.min(...sites.map(x=>Math.max(1,Number(x.interval||5))))}:{venue:getPerson().branch,branch:getPerson().branch,radius:200,accuracy:100,required:false,employeeExempt:true,interval:5};}
function geoReading(g){const value=state.geoReadings?.[g.id]||{};return {siteId:g.id,venue:g.venue,radius:Number(g.radius||200),accuracyLimit:Number(g.accuracy||100),accuracy:state.geo==='accuracy'?Math.max(Number(g.accuracy||100)+50,250):Number(value.accuracy??state.geoAccuracy??25),distance:state.geo==='outside'?Math.max(Number(g.radius||200)+100,680):Number(value.distance??state.geoDistance??85)};}
function checkGeo(){const sites=gpsSites();if(getPerson().role!=='專櫃')return {blocked:false,label:'員工帳號免 GPS 範圍限制',checks:[]};if(!sites.length)return {blocked:true,unconfigured:true,label:'尚未設定專櫃適用地點',checks:[]};const checks=sites.map(geoReading);if(['denied','timeout','offline'].includes(state.geo))return {blocked:true,label:({denied:'尚未取得定位授權',timeout:'定位逾時',offline:'目前無法連線驗證'})[state.geo],checks};const passed=checks.find(x=>x.accuracy<=x.accuracyLimit&&x.distance<=x.radius),valid=checks.find(x=>x.accuracy<=x.accuracyLimit),selected=passed||valid||checks[0];return {...selected,blocked:!passed,label:passed?'位於允許範圍':valid?'目前位於所有允許範圍之外':'定位精度不足',checks,matchedSiteId:passed?.siteId};}
function log(action){state.audit??=[];state.audit.unshift({at:stamp(),action,actor:getPerson().name,role:state.role,branch:getPerson().branch});state.audit=state.audit.slice(0,300);}
function trackSession(){state.sessionLog.unshift({id:'session-'+Date.now(),userId:state.userId,name:getPerson().name,account:getPerson().account+(state.identity==='counter'?' 共用專櫃帳號':' 員工帳號'),mode:state.mode,at:stamp(),status:'使用中',geo:checkGeo().label});state.sessionLog=state.sessionLog.slice(0,40);}
function go(v){if(!titles[v])v='home';if(state.role==='system'&&[...learningViews,...chatViews,'notices','notice','notifications','profile'].includes(v))return toast('系統管理員不查閱學習內容，請切換教育訓練角色');if(adminViews.includes(v)&&state.role==='learner')return toast('此頁需要管理角色');if(v==='notice'&&!activeNotice()){toast('目前身分沒有此公告的存取權');v='notices';}view=v;location.hash=v;render();}
function toast(text){const t=document.getElementById('toast');if(!t)return;t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function modal(html){const root=document.getElementById('modal-root');root.innerHTML='<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-label="操作視窗"><span class="sheet-handle"></span><button class="close" data-action="close" aria-label="關閉">×</button>'+html+'</section></div>';root.querySelector('button')?.focus();}
function closeModal(){document.getElementById('modal-root').innerHTML='';}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.Demo={state,save,go,toast,modal,closeModal,icon,esc,getPerson,getLearner,syncAssignments,getGps,checkGeo,getNotices,log,download,render};
const header=()=>'<div class="page-title"><span class="eyebrow">'+titles[view][0]+'</span><h1>'+titles[view][1]+'</h1></div>';
const navRow=(v,i,t,s='')=>'<button class="list-item full" data-go="'+v+'"><span class="list-icon">'+icon(i)+'</span><span class="grow"><strong>'+t+'</strong>'+(s?'<small class="muted">'+s+'</small>':'')+'</span>'+icon('arrow')+'</button>';
const pendingNotices=()=>getNotices().filter(n=>n.required&&!receipt(n).signedAt).length;
const unreadNotices=()=>getNotices().filter(n=>!receipt(n).readAt).length;
const noticeCountCaption=()=>'<span class="'+(unreadNotices()?'count-alert':'')+'">未讀 '+unreadNotices()+'</span> · 未簽 '+pendingNotices();
function notices(){const filter=state.noticeFilter||'pending',list=getNotices().filter(n=>filter==='all'||filter==='pending'&&n.required&&!receipt(n).signedAt||filter==='signed'&&receipt(n).signedAt);return header()+'<p class="muted">'+noticeCountCaption()+'（待本人確認）</p><div class="chips">'+[['pending','待確認'],['all','全部'],['signed','已確認']].map(([v,t])=>'<button class="chip '+(filter===v?'active':'')+'" data-action="notice-filter" data-value="'+v+'">'+t+'</button>').join('')+'</div>'+list.map(n=>{const r=receipt(n);return '<button class="card full notice-card" data-action="notice-open" data-id="'+esc(n.id)+'"><div class="row between"><span class="badge '+(!r.signedAt&&n.required?'warn':'gray')+'">'+(r.signedAt?'已確認':!n.required?'一般資訊':r.readAt?'已讀待確認':'未讀')+'</span><span class="tiny muted">'+esc(n.publishedAt.slice(5,10))+'</span></div><h3>'+esc(n.title)+'</h3><p class="small muted">'+esc(n.publisher)+' · '+esc(n.version)+'</p><div class="row between tiny"><span>'+(r.signedAt?'確認於 '+esc(r.signedAt):n.required?'確認期限 '+esc(n.due):'無須簽收')+'</span>'+icon('arrow')+'</div></button>';}).join('')+(list.length?'':'<div class="empty">'+icon('check')+'<h3>目前沒有待處理的公告</h3><p>可切換「全部」查看已發布內容。</p></div>');}
function noticeSecondsLeft(n){return n.important?Math.max(0,Math.ceil(NOTICE_MIN_SECONDS-(performance.now()-noticeOpenedAt)/1000)):0;}
function noticeCanConfirm(n){return !!n&&view==='notice'&&noticeReached&&noticeSecondsLeft(n)===0&&!!document.getElementById('ack-check')?.checked;}
function startNoticeReading(n){const r=receipt(n);r.readAt||=stamp();syncAssignments();noticeReached=false;noticeOpenedAt=performance.now();const panel=document.getElementById('notice-body'),check=document.getElementById('ack-check'),button=document.getElementById('ack-btn'),hint=document.getElementById('read-hint');const update=()=>{if(panel.scrollTop+panel.clientHeight>=panel.scrollHeight-4)noticeReached=true;const left=noticeSecondsLeft(n);if(check)check.disabled=!noticeReached;if(button){button.disabled=!noticeCanConfirm(n);button.innerHTML=left?'請閱讀 '+left+' 秒後確認':'確認已閱讀 '+icon('check');}if(hint)hint.textContent=noticeReached?(left?'已讀至底部，請停留至倒數結束後確認。':'已讀至底部，請勾選並完成本人確認。'):'請將上方公告內容捲動至底部';if(!left){clearInterval(noticeTimer);noticeTimer=null;}};panel?.addEventListener('scroll',update);panel?.querySelector('img')?.addEventListener('load',update);check?.addEventListener('change',update);if(n.important&&!r.signedAt&&n.required)noticeTimer=setInterval(update,200);update();}
function noticeAttachment(index){const n=activeNotice(),attachment=n?.attachments?.[index];if(!attachment)return;modal('<h2>'+esc(attachment.name)+'</h2><p>附件僅供檢視，不提供下載</p>'+(/\.pdf$/i.test(attachment.src)?'<iframe class="notice-attachment-view" title="'+esc(attachment.name)+'" src="'+esc(attachment.src)+'#toolbar=0&navpanes=0"></iframe>':'<img class="notice-attachment-image" src="'+esc(attachment.src)+'" alt="'+esc(attachment.name)+'">')+'<p class="tiny muted">示範僅隱藏下載入口，正式版需由伺服器限制原檔取得</p>');}
function notice(){const n=activeNotice();if(!n)return '<div class="empty">公告不存在或沒有權限</div>';const r=receipt(n);return '<button class="backline" data-go="notices">'+icon('back')+'公告中心</button><span class="badge '+(r.signedAt?'good':'warn')+'">'+(r.signedAt?'已完成本人確認':n.required?'待本人確認':'一般資訊')+'</span><h1 class="notice-title">'+esc(n.title)+'</h1><p class="small muted">'+esc(n.publisher)+' · '+esc(n.version)+'<br>'+esc(n.publishedAt)+' · '+esc(n.due)+' 前確認</p><div class="notice-body" id="notice-body" tabindex="0" aria-label="公告內文，請向下捲動至底部">'+(n.image?'<img class="notice-image" src="'+esc(n.image)+'" alt="'+esc(n.title)+'公告圖片">':'')+n.body.split('\n\n').map(t=>'<p>'+esc(t).replace(/\n/g,'<br>')+'</p>').join('')+'<p class="notice-end">— 已閱讀至本篇結尾 —</p></div>'+((n.attachments||[]).length?'<div class="notice-attachments"><h3>附件</h3>'+(n.attachments||[]).map((a,i)=>'<button class="secondary full" data-action="notice-attachment" data-index="'+i+'">'+icon('file')+'開啟 '+esc(a.name)+'</button>').join('')+'</div>':'')+(n.important?'<p class="tiny muted">重要公告須停留 '+NOTICE_MIN_SECONDS+' 秒並閱讀至底部後確認。</p>':'')+(r.signedAt?'<div class="alert success">'+icon('check')+'<div><strong>本人確認已完成</strong><br>'+esc(getPerson().name)+' · '+esc(n.version)+'<br>'+esc(r.signedAt)+'</div></div><button class="secondary full" data-action="receipt-download">下載確認回條</button>':n.required?'<p class="scrollhint" id="read-hint">請將上方公告內容捲動至底部</p><label class="check-row"><input id="ack-check" type="checkbox" disabled><span>我已閱讀並理解本公告內容</span></label><button id="ack-btn" class="primary full" data-action="ack-preview" disabled>確認已閱讀 '+icon('check')+'</button>':'<div class="alert">一般資訊公告，已記錄本次開啟時間。</div>')+'<p class="tiny muted">確認紀錄依使用人、公告及版本分開保存。</p>';}
function shared(){return '<section><span class="eyebrow">TEAMSYNC PORTAL</span><h1>共用模組</h1><p class="muted">AD／人員與帳號為一期平行相依；GPS 運作與可信裝置紀錄屬後續。共用主檔供各模組引用。</p><div class="card list-card">'+(state.role!=='learner'?navRow('people','users','共用人員與組織','來源與補充資料；AD 同步未接線')+navRow('accounts','users','共用帳號與匯入','員工／專櫃／部門 CSV')+navRow('gps-admin','map','共用 GPS 設定','後續執行；本機模擬'):'')+navRow('devices','shield','登入裝置紀錄','模擬資料')+navRow('portal','home','返回 portal 首頁')+'</div><p class="small muted">system 角色保留，只維護共用主檔，不查閱課程／成績。最高管理者寫入權待決。</p></section>';}
function todoItems(){if(state.role==='system')return [];const courses=(window.LearningUI?.getCourses?.()||[]).filter(c=>window.LearningUI.isAvailable(c)),l=getLearner();const items=courses.filter(c=>!l.courses[c.id]?.passed||(state.assignments||[]).some(a=>a.person===state.userId&&a.courseId===c.id&&a.reinforcement&&a.status!=='已完成')).map(c=>({id:'course:'+c.id,type:'course',contentId:c.id,title:c.title}));return items.concat(getNotices().filter(n=>n.required&&!receipt(n).signedAt).map(n=>({id:'notice:'+n.id+':'+n.version,type:'notice',contentId:n.id,title:n.title})));}
function todoSummary(){const items=todoItems();return {courses:items.filter(x=>x.type==='course').length,notices:items.filter(x=>x.type==='notice').length,total:items.length};}
window.Demo.todoSummary=todoSummary;
function portal(){
 const p=getPerson(),counts=todoSummary(),unread=unreadNotices();
 const modules=state.role==='system'?[['shared','settings','共用模組','人員、帳號、GPS 與裝置']]:[['home','book','E Learning',counts.courses?'未完成 '+counts.courses:'已全部完成',counts.courses>0],['chat','chat','AI 聊天室','財務知識問答'],['notices','bell','公告欄','未讀 '+unread,unread>0],['notifications','bell','通知待辦','總計 '+counts.total,counts.total>0],['records','chart','學習紀錄','時數與學習成果'],['shared','settings','共用模組','人員、帳號、GPS 與裝置']];
 if(!['learner','system'].includes(state.role))modules.push(['admin','settings','學習管理台','派課、審核與追蹤']);
 const tile=([route,ico,label,caption,alert])=>'<button class="ts-module" data-go="'+route+'"><span class="ts-module-icon">'+icon(ico)+'</span><strong class="ts-module-label">'+label+'</strong><span class="ts-module-caption'+(alert?' count-alert':'')+'">'+caption+'</span></button>';
 return '<section class="ts-portal"><div class="ts-company"><img src="assets/feds-logo.png" alt="遠東百貨"><h1>遠東百貨</h1><p>TeamSync · 一期 RWD／後續 App 整合</p></div><div class="ts-portal-section"><div class="ts-section-heading"><h2>我的最愛</h2><span class="tiny muted">'+esc(p.name)+'，你好</span></div><div class="ts-module-grid ts-favorites">'+modules.slice(0,2).map(tile).join('')+'</div></div><div class="ts-portal-section"><h2>全部功能</h2><div class="ts-module-grid">'+modules.map(tile).join('')+'</div></div>'+(state.role==='system'?'':'<p class="small muted">未完成課程 '+counts.courses+'；公告未讀 '+unread+'（尚未開啟），未簽 '+counts.notices+'（尚未確認）。通知待辦總計 '+counts.total+' ＝ 未完成 '+counts.courses+' ＋ 未簽公告 '+counts.notices+'。已讀通知仍保留至完成／簽收；本次不含聊天通知。</p>')+'</section>';
}

function profile(){
 const p=getPerson(),l=getLearner(),completed=Object.values(l.courses).flatMap(c=>[...(c.versionHistory||[]),c]).filter(c=>c.passed),hours=completed.reduce((a,c)=>a+Number(c.creditedHours||0),0);
 const info=(label,value)=>'<div class="ts-setting-row"><span>'+label+'</span><strong class="ts-value">'+esc(value||'—')+'</strong></div>';
 return '<section class="ts-profile"><div class="ts-profile-head"><div class="ts-profile-avatar">'+esc(p.name.slice(-1))+'</div><h1>'+esc(p.name)+'</h1><p>'+esc(p.branch)+' · '+esc(p.department)+'</p></div><div class="ts-settings">'+info('帳號',p.account)+info('目前使用人',p.name)+info('部門',p.department)+info('業務線',p.businessLine)+info('帳號類型',state.identity==='counter'?'專櫃共用帳號':'員工個人帳號')+'</div><h3 class="ts-settings-title">學習與工作</h3><div class="card list-card">'+navRow('records','chart','學習紀錄',completed.length+' 堂已完成 · '+TrainingTime.format(hours*3600)+'（HH:mm:ss）')+navRow('notices','bell','公告確認',noticeCountCaption())+navRow('chat-saved','chat','收藏回答','查看已收藏的對話重點')+'</div><h3 class="ts-settings-title">帳號與設定</h3><div class="card list-card">'+navRow('gps','map','位置與使用權限',state.identity==='employee'?'員工免 GPS 範圍限制':checkGeo().label)+navRow('devices','shield','登入裝置紀錄','工作階段與撤銷示範')+(state.role!=='learner'?navRow('admin','settings','管理工作台',roleNames[state.role]):'')+'</div><button class="secondary full" data-action="identity-switch">'+icon('users')+'切換使用人</button><button class="link-button full" data-go="login">登入與帳號設定</button><p class="tiny muted text-center">TeamSync AI · 遠百經典</p></section>';
}
function gps(){const g=getGps(),r=checkGeo(),sites=gpsSites();return header()+'<span class="badge '+(r.blocked?'warn':'good')+'">'+r.label+'</span><div class="map-demo"><div class="pin">'+icon('map')+'</div><div class="label">'+esc(r.venue||g.venue)+'</div><div class="map-caption">範圍示意 · 非真實地圖與定位</div></div><p class="small muted">'+(getPerson().role==='專櫃'?'符合目前館別、業務線與綁定對象的任一啟用地點通過，即可使用。':'員工帳號免 GPS 範圍限制。')+'</p><h3 class="section-title">定位情境</h3><div class="chips">'+[['inside','範圍內'],['outside','範圍外'],['denied','未授權'],['timeout','逾時'],['accuracy','精度不足'],['offline','離線']].map(([v,t])=>'<button class="chip '+(state.geo===v?'active':'')+'" data-action="geo" data-value="'+v+'">'+t+'</button>').join('')+'</div><div class="stack">'+sites.map(site=>{const q=geoReading(site);return '<div class="card stack"><div class="row between"><strong>'+esc(site.venue)+'</strong><span class="badge '+(r.matchedSiteId===site.id?'good':'gray')+'">'+(r.matchedSiteId===site.id?'已匹配':'待檢核')+'</span></div><p class="small muted">'+esc(site.branch)+' · 半徑 '+q.radius+'m · 精度上限 '+q.accuracyLimit+'m<br>每 '+Number(site.interval||5)+' 分鐘前景檢查</p><label class="field">'+esc(site.venue)+'：模擬距離（公尺）<input data-geo-id="'+esc(site.id)+'" data-geo-kind="distance" type="number" min="0" max="50000" value="'+Number(state.geoReadings?.[site.id]?.distance??state.geoDistance??85)+'"></label><label class="field">'+esc(site.venue)+'：模擬精度（公尺）<input data-geo-id="'+esc(site.id)+'" data-geo-kind="accuracy" type="number" min="1" max="5000" value="'+Number(state.geoReadings?.[site.id]?.accuracy??state.geoAccuracy??25)+'"></label></div>';}).join('')+'</div>'+(sites.length?'<button class="secondary full" data-action="geo-test">依各地點距離重新檢查</button>':'<div class="card">'+(getPerson().role==='專櫃'?'尚未設定適用地點，請由管理者完成帳號綁定。原型暫停專櫃功能，正式例外政策待確認。':'員工帳號免 GPS 範圍限制。')+'</div>')+'<div class="alert">登入、回到前景及使用期間共用位置限制。範圍外保留學習進度。此版未讀取真實位置；多地點距離為獨立示範輸入。</div><button class="primary full" data-go="home">回到學習 '+icon('arrow')+'</button>';}

function block(){return '<div class="empty access-block"><span class="list-icon large">'+icon('shield')+'</span><h2>'+checkGeo().label+'</h2><p>專櫃帳號需在授權範圍內使用。<br>課程進度與確認紀錄已保留。</p><button class="primary full" data-go="gps">檢查位置與重試</button><button class="secondary full" data-go="login">返回登入</button><p class="tiny muted">目前是定位限制示範，正式存取由服務端共同驗證。</p></div>';}
function notifications(){const items=todoItems(),counts=todoSummary();return header()+'<p>未完成 '+counts.courses+' ＋ 未簽公告 '+counts.notices+' ＝ 通知待辦 '+counts.total+'</p><button class="link-button" data-action="notification-read-all">全部標為已讀</button>'+items.map(a=>'<button class="card full notice-card" data-action="todo-open" data-type="'+a.type+'" data-id="'+esc(a.contentId)+'"><span class="badge">'+(state.notificationReads[a.id]?'通知已讀':'通知未讀')+' · 待完成</span><h3>'+esc(a.title)+'</h3><p class="small muted">'+(a.type==='course'?'課程未完成':'公告未簽收')+'</p></button>').join('')+'<p class="small muted">與入口 tile 共用示範待辦來源；通知已讀不扣除尚未完成的課程或未簽公告。總數暫不含聊天。</p>';}

function login(){return '<div class="login-brand"><img src="assets/feds-logo.png" alt="遠東百貨 LOGO"><span>遠百學習<small>POWERED BY TEAMSYNC</small></span></div><span class="eyebrow">WELCOME BACK</span><h1>把專業，<br>帶進每一天。</h1><p class="muted">遠東百貨 · 財務教育訓練</p><div class="card stack"><h3>員工登入</h3><button class="primary full" data-action="login-employee">企業 AD / SSO 登入示範</button><button class="secondary full" data-action="login-password">使用員工帳號示範</button><p class="tiny muted">員工不受 GPS 範圍限制；停用狀態共用。</p></div><div class="card stack"><h3>專櫃夥伴</h3><p class="small muted">先確認目前使用人，再檢查位置範圍。</p><button class="secondary full" data-action="login-counter">專櫃帳號登入示範</button></div><p class="tiny muted text-center">DEMO 使用示範帳號，不連接遠百正式登入服務。</p>';}
function identitySheet(counter=state.identity==='counter'){const people=(state.people||[]).filter(p=>!['離職','停用'].includes(p.status)&&p.role===(counter?'專櫃':'員工')&&(!counter||getPerson().role!=='專櫃'||p.account===getPerson().account));modal('<span class="eyebrow">ACCOUNT & IDENTITY</span><h2>'+(counter?'專櫃帳號 · 確認使用人':'選擇示範使用人')+'</h2><p class="small muted">不同人的課程、測驗、AI 對話與公告回條分開保存。</p><label class="field">目前操作人<select id="identity-person">'+people.map(p=>'<option value="'+esc(p.id)+'" '+(p.id===state.userId?'selected':'')+'>'+esc(p.name)+' · '+esc(p.branch)+'</option>').join('')+'</select></label>'+(counter?'<label class="check-row"><input id="location-consent" type="checkbox"><span>我瞭解專櫃帳號會於登入及前景使用時檢查位置範圍。</span></label>':'')+'<button class="primary full" data-action="identity-confirm" data-counter="'+(counter?'1':'0')+'">確認目前使用人</button>');}
function devices(){return window.DevicesUI?.render()||header();}
const canEditNotices=()=>['branch','business'].includes(state.role);
function managedNotices(){const p=getPerson();return [...state.noticeCatalog,...(state.noticeDrafts||[])].filter(n=>state.role==='executive'||n.businessLine===p.businessLine&&(state.role==='business'||state.role==='branch'&&n.branches.includes(p.branch)));}
function noticeManagement(){return header()+'<p class="muted">發布內容、版本與閱讀確認政策。</p>'+(canEditNotices()?'<button class="primary full" data-action="notice-new">'+icon('bell')+'建立公告</button>':'<div class="alert">目前角色僅可檢視與匯出。</div>')+'<div class="stack" style="margin-top:18px">'+managedNotices().map(n=>'<div class="card"><div class="row between"><span class="badge '+(n.status==='已發布'?'good':'gray')+'">'+esc(n.status)+'</span><span class="tiny muted">'+esc(n.version)+'</span></div><h3>'+esc(n.title)+'</h3><p class="small muted">'+esc(n.publisher)+' · '+esc(n.branches.join('、'))+'<br>'+(n.required?'需要本人確認':'一般資訊')+' · '+esc(n.due)+'</p><div class="row"><button class="secondary grow" data-action="notice-edit" data-id="'+esc(n.id)+'">'+(canEditNotice(n)?'編輯／新版本':'查看內容')+'</button><button class="secondary grow" data-action="notice-tracking" data-id="'+esc(n.id)+'">確認紀錄</button></div>'+(n.status!=='已發布'&&canEditNotice(n)?'<button class="primary full" data-action="notice-publish" data-id="'+esc(n.id)+'">發布此版本</button>':'')+'</div>').join('')+'</div>';}
function noticeEditor(id){const n=(state.noticeDrafts||[]).find(x=>x.id===id)||state.noticeCatalog.find(x=>x.id===id),edit=canEditNotice(n);modal('<span class="eyebrow">ANNOUNCEMENT EDITOR</span><h2>'+(n?'公告內容與版本':'建立新公告')+'</h2><div class="stack"><label class="field">公告標題<input id="notice-title" maxlength="80" value="'+esc(n?.title||'')+'" '+(!edit?'disabled':'')+'></label><label class="field">公告內容<textarea id="notice-text" rows="8" '+(!edit?'disabled':'')+'>'+esc(n?.body||'')+'</textarea></label><label class="field">圖片<select id="notice-image" '+(!edit?'disabled':'')+'><option value="">無</option>'+NOTICE_IMAGES.map(src=>'<option value="'+esc(src)+'" '+(n?.image===src?'selected':'')+'>'+esc(src.split('/').pop())+'</option>').join('')+'</select></label><fieldset class="notice-attachment-options"><legend>附件（僅供檢視）</legend>'+NOTICE_ATTACHMENTS.map(a=>'<label class="check-row"><input type="checkbox" name="notice-attachment" value="'+esc(a.src)+'" '+(n?.attachments?.some(x=>x.src===a.src)?'checked':'')+' '+(!edit?'disabled':'')+'><span>'+esc(a.name)+'</span></label>').join('')+'</fieldset><label class="check-row"><input id="notice-important" type="checkbox" '+(n?.important?'checked':'')+' '+(!edit?'disabled':'')+'><span>重要公告：須停留 '+NOTICE_MIN_SECONDS+' 秒才能確認</span></label><label class="field">完成期限<input id="notice-due" type="date" value="'+esc(n?.due||'2026-10-30')+'" '+(!edit?'disabled':'')+'></label><label class="check-row"><input id="notice-required" type="checkbox" '+(n?.required!==false?'checked':'')+' '+(!edit?'disabled':'')+'><span>要求閱讀至底部並完成本人確認</span></label><label class="field">適用館別<select id="notice-branch" '+(!edit?'disabled':'')+'><option value="'+esc(getPerson().branch)+'">'+esc(getPerson().branch)+'</option>'+(state.role==='business'?'<option value="all" '+(n?.branches.length>1?'selected':'')+'>全館財務業務線</option>':'')+'</select></label>'+(n?.status==='已發布'?'<div class="alert">已發布內容以新版本保存；原有回條保留，新版發布後須重新確認。</div>':'')+(edit?'<button class="primary full" data-action="notice-save" data-id="'+esc(id||'')+'">儲存'+(n?.status==='已發布'?'新版本':'草稿')+'</button>':'')+'</div>');}
function saveNotice(id){const old=(state.noticeDrafts||[]).find(n=>n.id===id)||state.noticeCatalog.find(n=>n.id===id);if(!canEditNotice(old))return toast('此公告超出編輯權限；跨館公告由業管單位維護');const title=document.getElementById('notice-title').value.trim(),body=document.getElementById('notice-text').value.trim(),due=document.getElementById('notice-due').value,branch=document.getElementById('notice-branch').value;if(!title||body.length<10||!due)return toast('請填標題、至少 10 字內文及期限');if(due<'2026-10-22')return toast('期限不可早於展示基準日 10/22');const n=Object.assign({},old||{id:'notice-'+Date.now(),publisher:'財務部',businessLine:getPerson().businessLine,ownerBranch:state.role==='branch'?getPerson().branch:'總公司'},{title,body,due,image:document.getElementById('notice-image').value,attachments:NOTICE_ATTACHMENTS.filter(a=>[...document.querySelectorAll('input[name="notice-attachment"]:checked')].some(input=>input.value===a.src)).map(a=>({...a})),important:document.getElementById('notice-important').checked,required:document.getElementById('notice-required').checked,branches:branch==='all'?[...new Set(state.people.filter(p=>p.businessLine===getPerson().businessLine).map(p=>p.branch))]:[branch],version:old?.status==='已發布'?'v'+(parseInt(versionKey(old.version))+1)+'.0':old?.version||'v1.0',status:'草稿',publishedAt:old?.publishedAt||stamp()});state.noticeDrafts??=[];const index=state.noticeDrafts.findIndex(x=>x.id===n.id);if(index<0)state.noticeDrafts.push(n);else state.noticeDrafts[index]=n;log('儲存公告草稿 '+title+' '+n.version);save();closeModal();go('notices-management');}
